D.cZM=new C.ly(9,517.27,0.16,0.54,"Magnesium","Mg","b\u2082","Mittlere der drei Magnesium-b-Linien (516,73 / 517,27 / 518,36 nm). Fraunhofer bezeichnete die Gruppe mit dem Buchstaben b.")
D.cZY=new C.ly(10,527,0.15,0.44,"Eisen","Fe","E","Von Fraunhofer mit E bezeichnete Eisenlinie im Gr\xfcnen.")
D.cZP=new C.ly(11,528.8,0.13,0.33,"Magnesium","Mg","","Magnesiumlinie im Gr\xfcnen, dicht neben der Eisenlinie E.")
D.d_2=new C.ly(12,532.8,0.14,0.38,"Eisen","Fe","","Kr\xe4ftige Eisenlinie; sie wird h\xe4ufig zur Bestimmung der Eisenh\xe4ufigkeit in Sternatmosph\xe4ren benutzt.")
D.d_3=new C.ly(13,547.69,0.11,0.28,"Nickel","Ni","","Nickellinie im Gr\xfcnen. Nickel ist rund zwanzigmal seltener als Eisen \u2013 seine Linien sind entsprechend schw\xe4cher.")
D.cZN=new C.ly(14,552.8,0.13,0.33,"Magnesium","Mg","","Magnesiumlinie im Gr\xfcnen, deutlich abseits des b-Tripletts.")
D.cZX=new C.ly(15,585.7,0.11,0.28,"Kalzium","Ca","","Schw\xe4chere Linie des neutralen Kalziums im Gelben, unmittelbar links vom Natrium-Dublett.")
D.cZR=new C.ly(16,588.99,0.2,0.72,"Natrium","Na","D\u2082","St\xe4rkere der beiden Natrium-D-Linien. Dieselbe Wellenl\xe4nge sendet eine Natriumdampflampe aus \u2013 daher das gelbe Licht von Stra\xdfenlaternen.")
D.d_1=new C.ly(17,589.59,0.2,0.66,"Natrium","Na","D\u2081","Schw\xe4chere Natriumlinie. Der Abstand von nur 0,6 nm zwischen D\u2081 und D\u2082 (Feinstruktur) ist erst bei starker Vergr\xf6\xdferung erkennbar.")
D.d__=new C.ly(18,610.27,0.11,0.28,"Kalzium","Ca","","Kalziumlinie im Orangen.")
D.cZT=new C.ly(19,627.66,0.12,0.38,"Sauerstoff","O\u2082","\u03b3","Diese Linie entsteht nicht in der Sonne, sondern im Sauerstoff der Erdatmosph\xe4re (tellurische Linie, \u03b3-Bande). Sie fehlt in Spektren, die au\xdferhalb der Atmosph\xe4re aufgenommen werden.")
D.cZS=new C.ly(20,656.28,0.28,0.6,"Wasserstoff","H","H\u03b1 (C)","Erste Balmer-Linie (n = 3 \u2192 2) im Roten, von Fraunhofer C genannt. In ihrem Licht beobachtet man Protuberanzen und Flares.")
