D.iSd=new A.z("Der K\xe4fer bewegt sich mit dem Rotorblatt auf einer Kreisbahn. Daf\xfcr ist eine st\xe4ndig zur Nabe gerichtete Zentripetalkraft n\xf6tig:",null,D.hn,null,null,null,null,null,null,null)
